CREATE TABLE IF NOT EXISTS adm_users (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,username VARCHAR(64) NOT NULL,display_name VARCHAR(128) NOT NULL,email VARCHAR(255),password_hash VARCHAR(255) NOT NULL,status VARCHAR(32) NOT NULL,mfa_secret_envelope BLOB,failed_login_count INT UNSIGNED NOT NULL DEFAULT 0,locked_until DATETIME(6),last_login_at DATETIME(6),password_changed_at DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_adm_users_username(username),KEY idx_adm_users_status(status),KEY idx_adm_users_deleted(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS adm_roles (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,description VARCHAR(512),data_scope VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_adm_roles_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS adm_permissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(128) NOT NULL,name VARCHAR(128) NOT NULL,resource VARCHAR(64) NOT NULL,action VARCHAR(64) NOT NULL,description VARCHAR(512),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_adm_permissions_code(code),KEY idx_adm_permissions_resource(resource)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS adm_role_bindings (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,admin_user_id BIGINT UNSIGNED NOT NULL,role_id BIGINT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_adm_role_binding(admin_user_id,role_id),KEY idx_adm_role_binding_role(role_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS adm_role_permissions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_adm_role_permission(role_id,permission_id),KEY idx_adm_role_permission_permission(permission_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS agt_agents (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,status VARCHAR(32) NOT NULL,contact_name VARCHAR(128),contact_phone VARCHAR(64),settlement_ref VARCHAR(128),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_agt_agents_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ent_enterprises (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,agent_id BIGINT UNSIGNED,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,status VARCHAR(32) NOT NULL,industry VARCHAR(128),region VARCHAR(128),timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Shanghai',locale VARCHAR(32) NOT NULL DEFAULT 'zh-CN',contact_name VARCHAR(128),contact_email VARCHAR(255),contact_phone VARCHAR(64),notification_json JSON,remark TEXT,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_ent_enterprises_code(code),KEY idx_ent_enterprises_status(status),KEY idx_ent_enterprises_agent(agent_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ent_accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,username VARCHAR(64) NOT NULL,email VARCHAR(255),phone VARCHAR(64),password_hash VARCHAR(255) NOT NULL,status VARCHAR(32) NOT NULL,must_change_password BOOLEAN NOT NULL DEFAULT FALSE,failed_login_count INT UNSIGNED NOT NULL DEFAULT 0,locked_until DATETIME(6),last_login_at DATETIME(6),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_ent_accounts_enterprise(enterprise_id),UNIQUE KEY uk_ent_accounts_username(username),KEY idx_ent_accounts_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ent_plans (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,status VARCHAR(32) NOT NULL,limits_json JSON NOT NULL,features_json JSON NOT NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_ent_plans_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ent_subscriptions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,plan_id BIGINT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL,starts_at DATETIME(6) NOT NULL,expires_at DATETIME(6) NOT NULL,auto_renew BOOLEAN NOT NULL DEFAULT FALSE,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_ent_subscriptions_enterprise_status(enterprise_id,status),KEY idx_ent_subscriptions_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ent_quota_limits (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,metric VARCHAR(64) NOT NULL,limit_value BIGINT NOT NULL,used_value BIGINT NOT NULL DEFAULT 0,reserved_value BIGINT NOT NULL DEFAULT 0,period VARCHAR(32) NOT NULL,reset_at DATETIME(6),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_ent_quota(enterprise_id,metric)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ent_usage_ledgers (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED NOT NULL,metric VARCHAR(64) NOT NULL,operation VARCHAR(32) NOT NULL,amount BIGINT NOT NULL,balance_after BIGINT NOT NULL DEFAULT 0,reference_type VARCHAR(64) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,idempotency_key VARCHAR(128) NOT NULL,reason VARCHAR(512),created_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_ent_usage_idempotency(idempotency_key),KEY idx_ent_usage_reference(reference_type,reference_id),KEY idx_ent_usage_enterprise_metric(enterprise_id,metric,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sec_login_sessions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,enterprise_id BIGINT UNSIGNED,subject_type VARCHAR(32) NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,audience VARCHAR(32) NOT NULL,refresh_token_hash CHAR(64) NOT NULL,device_id VARCHAR(128),ip_address VARCHAR(64),user_agent VARCHAR(512),expires_at DATETIME(6) NOT NULL,last_seen_at DATETIME(6) NOT NULL,revoked_at DATETIME(6),revoke_reason VARCHAR(255),created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_sec_session_token(refresh_token_hash),KEY idx_sec_session_subject(subject_type,subject_id,revoked_at),KEY idx_sec_session_enterprise(enterprise_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_prompt_templates (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,purpose VARCHAR(64) NOT NULL,description VARCHAR(1024),status VARCHAR(32) NOT NULL,current_version_id BIGINT UNSIGNED,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_prompt_code(code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_prompt_versions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,prompt_template_id BIGINT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL,system_prompt LONGTEXT NOT NULL,template LONGTEXT NOT NULL,variables_json JSON NOT NULL,output_schema_json JSON,checksum CHAR(64) NOT NULL,change_summary VARCHAR(1024),published_by BIGINT UNSIGNED,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_cfg_prompt_version(prompt_template_id,version_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_article_types (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,description VARCHAR(1024),icon VARCHAR(255),source_type VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,visible BOOLEAN NOT NULL DEFAULT TRUE,sort_order INT NOT NULL DEFAULT 0,current_version_id BIGINT UNSIGNED,visibility_json JSON,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_article_type_code(code),KEY idx_cfg_article_type_list(status,visible,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_article_type_versions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,article_type_id BIGINT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL,content_goal TEXT,target_audience TEXT,tone VARCHAR(128),recommended_min_words INT UNSIGNED NOT NULL DEFAULT 0,recommended_max_words INT UNSIGNED NOT NULL DEFAULT 0,structure_json JSON NOT NULL,input_schema_json JSON NOT NULL,geo_rules_json JSON NOT NULL,quality_rules_json JSON NOT NULL,prompt_version_id BIGINT UNSIGNED NOT NULL,default_model_id BIGINT UNSIGNED,fallback_model_ids_json JSON,change_summary VARCHAR(1024),published_by BIGINT UNSIGNED,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_cfg_article_type_version(article_type_id,version_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_writing_models (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,display_name VARCHAR(128) NOT NULL,provider VARCHAR(64) NOT NULL,protocol VARCHAR(32) NOT NULL,base_url VARCHAR(512) NOT NULL,model_id VARCHAR(128) NOT NULL,credential_ref VARCHAR(255),context_length INT UNSIGNED NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL,sort_order INT NOT NULL DEFAULT 0,purposes_json JSON NOT NULL,parameters_json JSON NOT NULL,safety_json JSON,pricing_json JSON,visibility_json JSON,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_writing_model_code(code),KEY idx_cfg_writing_model_list(status,provider,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sec_writing_model_credentials (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,writing_model_id BIGINT UNSIGNED NOT NULL,key_id VARCHAR(128) NOT NULL,algorithm VARCHAR(64) NOT NULL,ciphertext BLOB NOT NULL,nonce VARBINARY(64) NOT NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_sec_writing_model(writing_model_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_publish_channels (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,category VARCHAR(32) NOT NULL,icon VARCHAR(512),description VARCHAR(1024),status VARCHAR(32) NOT NULL,authorization_type VARCHAR(32) NOT NULL,execution_mode VARCHAR(32) NOT NULL,capabilities_json JSON NOT NULL,rules_json JSON,visibility_json JSON,driver_version VARCHAR(64),sort_order INT NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_publish_channel_code(code),KEY idx_cfg_publish_channel_list(category,status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_publish_targets (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,publish_channel_id BIGINT UNSIGNED NOT NULL,name VARCHAR(255) NOT NULL,target_type VARCHAR(32) NOT NULL,platform VARCHAR(128),entry_url VARCHAR(1024),submission_email VARCHAR(255),region VARCHAR(128),industry VARCHAR(128),contact_envelope BLOB,cooperation_json JSON,requirements_json JSON,status VARCHAR(32) NOT NULL,sort_order INT NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),KEY idx_cfg_publish_target_channel(publish_channel_id,status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cfg_inclusion_sites (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,code VARCHAR(64) NOT NULL,name VARCHAR(128) NOT NULL,entry_url VARCHAR(1024) NOT NULL,icon VARCHAR(512),status VARCHAR(32) NOT NULL,authorization_type VARCHAR(32) NOT NULL,capabilities_json JSON NOT NULL,model_entries_json JSON,evidence_rules_json JSON NOT NULL,limits_json JSON,availability_json JSON,visibility_json JSON,driver_version VARCHAR(64),maintenance_message VARCHAR(1024),sort_order INT NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,deleted_at DATETIME(6),PRIMARY KEY(id),UNIQUE KEY uk_cfg_inclusion_site_code(code),KEY idx_cfg_inclusion_site_list(status,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
